  c.attr('data-tip', 'Step ' + k + ': φ₀=' + p[0].toFixed(2) + ', φ₁=' + p[1].toFixed(2) + ', L=' + loss(p[0], p[1]).toFixed(2));
  c.on('mousemove', function (e) { showTooltip(this.attr('data-tip'), e); }).on('mouseleave', hideTooltip);
  c.on('click', function () { showPopup('Descent step ' + k, 'One step of gradient descent on the loss surface. Each numbered point is a parameter pair — and the matching numbered line in panel b.'); });
  c.css('cursor', 'pointer');
  gTrail.text(String(k)).center(ax(p[0]), ay(p[1]) + 20).font({ size: 13, fill: '#eee', 'paint-order': 'stroke' }).stroke({ color: '#333', width: 2 }).attr({ 'stroke-linejoin': 'round' });
});

/* ── Panel b: data + lines ── */
draw.rect(B.x1 - B.x0, B.y1 - B.y0).move(B.x0, B.y0).fill('#fff').stroke({ color: '#222', width: 1.5 });
[[0, '0.0'], [1, '1.0'], [2, '2.0']].forEach(function (t) {
  draw.line(bx(t[0]), B.y1, bx(t[0]), B.y1 + 5).stroke('#222');
  draw.text(t[1]).center(bx(t[0]), B.y1 + 16).font({ size: 12, fill: '#333' });
  draw.line(B.x0 - 5, by(t[0]), B.x0, by(t[0])).stroke('#222');
  draw.text(t[1]).center(B.x0 - 16, by(t[0]) + 4).font({ size: 12, fill: '#333' });
});
draw.text('Input, x').center((B.x0 + B.x1) / 2, B.y1 + 36).font({ size: 15, fill: '#111' });
draw.text('Output, y').center(B.x0 - 42, (B.y0 + B.y1) / 2).font({ size: 15, fill: '#111' }).rotate(-90, B.x0 - 42, (B.y0 + B.y1) / 2);
draw.text('b)').font({ size: 18, fill: '#111' }).move(468, 18);

var DATA = [[0.1, 0.55], [0.3, 0.8], [0.45, 1.05], [0.6, 1.0], [0.75, 1.3], [0.85, 1.15],
            [1.05, 1.45], [1.2, 1.1], [1.3, 1.55], [1.5, 1.5], [1.6, 1.65], [1.85, 1.5]];
DATA.forEach(function (d) {
  var c = draw.circle(15).center(bx(d[0]), by(d[1])).fill('#e07b54').stroke({ color: '#a34a28', width: 1 });
  c.on('mousemove', function (e) { showTooltip('training point', e); }).on('mouseleave', hideTooltip);
});

/* line from parameters: y = φ0 + 0.16·φ1·x */
function lineY(p0, p1, x) { return p0 + 0.16 * p1 * x; }
function drawLineInB(group, p0, p1, stroke, width, opacity) {
  var xs = [], ys = [];
  var xA = 0, xB = 2, yA = lineY(p0, p1, xA), yB = lineY(p0, p1, xB);
  // clip to y in [0,2] roughly: just draw across full x range
  group.line(bx(xA), by(Math.max(-0.5, Math.min(2.5, yA))), bx(xB), by(Math.max(-0.5, Math.min(2.5, yB))))
    .stroke({ color: stroke, width: width, opacity: opacity, linecap: 'round' });
}
var clipB = draw.rect(B.x1 - B.x0, B.y1 - B.y0).move(B.x0, B.y0);
var gLines = draw.group(); gLines.clipWith(clipB);
TRAJ.forEach(function (p, k) {
  drawLineInB(gLines, p[0], p[1], TEALS[k], 4, 0.75);
});
TRAJ.forEach(function (p, k) {
  var yAt = lineY(p[0], p[1], 0.12);
  if (yAt > 0.05 && yAt < 1.9)
    draw.text(String(k)).center(bx(0.12) - 14, by(yAt) + 4).font({ size: 13, fill: TEALS[k] });
});
var gCur = draw.group(); gCur.clipWith(clipB);

/* ── Current marker (draggable) ── */
var cur = { p0: 0.2, p1: 0.2 };
var CURCOL = '#083d37';
var marker = draw.group();
var mcirc = marker.circle(22).fill(CURCOL).stroke({ color: '#fff', width: 2.5 });
marker.on('mousemove', function (e) { if (!dragging) showTooltip('drag me: current (φ₀, φ₁)', e); })
      .on('mouseleave', hideTooltip);
marker.css('cursor', 'grab');

var readoutEl = document.getElementById('paramReadout');

function render() {
  gCur.clear();
  drawLineInB(gCur, cur.p0, cur.p1, CURCOL, 5, 1);
  marker.center(ax(cur.p0), ay(cur.p1));
  readoutEl.textContent = 'φ₀=' + cur.p0.toFixed(2) + '  φ₁=' + cur.p1.toFixed(2) + '  L=' + loss(cur.p0, cur.p1).toFixed(3);
}
function setParams(p0, p1, updateSliders) {
  cur.p0 = Math.max(PHI0[0], Math.min(PHI0[1], p0));
  cur.p1 = Math.max(PHI1[0], Math.min(PHI1[1], p1));
  if (updateSliders !== false) {
    document.getElementById('interceptSliderInput').value = cur.p0;
    document.getElementById('slopeSliderInput').value = cur.p1;
    document.getElementById('interceptSliderVal').value = cur.p0.toFixed(2);
    document.getElementById('slopeSliderVal').value = cur.p1.toFixed(2);
  }
  render();
}
function update_interceptSlider(v) { setParams(v, cur.p1); }
function update_slopeSlider(v) { setParams(cur.p0, v); }

/* drag handling */
var dragging = false;
marker.on('pointerdown', function (e) { dragging = true; marker.css('cursor', 'grabbing'); hideTooltip(); e.preventDefault(); });
window.addEventListener('pointermove', function (e) {
  if (!dragging) return;
  var pt = draw.point(e.clientX, e.clientY);
  var p0 = PHI0[0] + (pt.x - A.x0) / A.s * (PHI0[1] - PHI0[0]);
  var p1 = PHI1[0] + (A.y0 + A.s - pt.y) / A.s * (PHI1[1] - PHI1[0]);
  setParams(p0, p1);
});
window.addEventListener('pointerup', function () { dragging = false; marker.css('cursor', 'grab'); });

/* ── Demo steps ── */
var STEPS = [
  { title: 'Follow the descent path',
    narration: 'Panel a shows the loss for every (φ₀, φ₁) pair; panel b shows the line each pair produces. The numbered trail 0→4 is a gradient descent run — each step moves to lower (lighter) loss and the matching line hugs the data more closely.',
    state: { interceptSlider: 0.2, slopeSlider: 0.2 } },
  { title: 'Move one parameter at a time',
    narration: 'Sweep the intercept slider: the line slides up and down in panel b while the marker moves horizontally on the loss surface. Then sweep the slope: the line rotates while the marker moves vertically. Each surface axis is one degree of freedom of the line.',
    state: { interceptSlider: 1, slopeSlider: 0.2 } },
  { title: 'Find the minimum by dragging',
    narration: 'Drag the marker on the loss surface until it sits in the lightest region — the fitted line now passes through the heart of the data cloud. You have just performed optimization by hand: the best fit is the bottom of the loss bowl.',
    state: { interceptSlider: 0.65, slopeSlider: 3.2 } }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[stepIdx];
  document.getElementById('demoNarration').textContent = (stepIdx + 1) + '. ' + s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = ' ' + (stepIdx + 1) + ' / ' + STEPS.length + ' ';
  setParams(s.state.interceptSlider, s.state.slopeSlider);
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Every choice of intercept φ₀ and slope φ₁ defines a line in data space and a single point on the loss surface — training a linear model means moving around that surface toward its minimum, and each step downhill visibly improves the fit to the data.
KEY INSIGHT (what students should walk away understanding): Fitting a line and minimizing a loss function are the same act: every parameter pair is both a line through the data and a height on the loss surface, and the best-fitting line sits exactly at the surface's minimum.
DEMO STEPS: 3 guided steps — implement the step player in #ui

FULL BLUEPRINT:
