// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
var W = 920, H = 440;
draw.viewbox(0, 0, W, H);

/* ── Panel geometry ── */
var A = { x0: 70, y0: 45, s: 350 };             // panel a plot box (square)
var B = { x0: 530, y0: 45, x1: 880, y1: 400 };  // panel b plot box
var PHI0 = [0, 2];                               // intercept domain (x axis)
var PHI1 = [-1, 1];                              // slope domain (y axis, -1 at TOP as in source)
function ax(p0) { return A.x0 + (p0 - PHI0[0]) / (PHI0[1] - PHI0[0]) * A.s; }
function ay(p1) { return A.y0 + (p1 - PHI1[0]) / (PHI1[1] - PHI1[0]) * A.s; } // p1=-1 → top
function bx(x) { return B.x0 + x / 2 * (B.x1 - B.x0); }
function by(y) { return B.y1 - y / 2 * (B.y1 - B.y0); }

/* ── Training data (matches source scatter) ── */
var DATA = [[0.05,0.60],[0.30,0.85],[0.42,1.12],[0.55,1.00],[0.85,1.38],[0.85,1.55],
            [1.15,0.95],[1.25,1.45],[1.55,1.55],[1.65,1.72],[1.70,1.62],[1.90,1.50]];

/* ── Loss: actual sum of squared residuals of y = φ0 + φ1·x ── */
function loss(p0, p1) {
  var s = 0;
  for (var i = 0; i < DATA.length; i++) {
    var r = DATA[i][1] - (p0 + p1 * DATA[i][0]);
    s += r * r;
  }
  return s;
}
/* exact quadratic form */
var N = DATA.length, Sx = 0, Sxx = 0, Sy = 0, Sxy = 0, Syy = 0;
DATA.forEach(function (d) { Sx += d[0]; Sxx += d[0]*d[0]; Sy += d[1]; Sxy += d[0]*d[1]; Syy += d[1]*d[1]; });
var QA = N, QB = Sxx, QC = Sx, QD = Sy, QE = Sxy;
var det = QA*QB - QC*QC;
var MIN = { p0: (QD*QB - QE*QC)/det, p1: (QA*QE - QC*QD)/det };   // least-squares solution
var LMIN = loss(MIN.p0, MIN.p1);
/* Renormalize to the loss range actually visible: deep maroon bowl with ONE
   light high-loss corner. Map [LMIN, ~2.5·LMIN] across the full ramp — linear,
   no sqrt, no corner-based LMAX, so the bowl reads dark as in the source. */
var LSPAN = Math.max(1e-9, 2.5 * LMIN - LMIN);

/* colormap: LOW loss = deep dark maroon, HIGH loss = salmon/orange (matches source) */
var STOPS = [[0, [26, 8, 6]], [0.3, [66, 26, 18]], [0.6, [126, 60, 44]], [0.85, [188, 112, 90]], [1, [228, 170, 145]]];
function cmap(t) {
  t = Math.max(0, Math.min(1, t));
  for (var i = 0; i < STOPS.length - 1; i++) {
    if (t <= STOPS[i + 1][0]) {
      var f = (t - STOPS[i][0]) / (STOPS[i + 1][0] - STOPS[i][0]);
      var c = STOPS[i][1].map(function (v, j) { return Math.round(v + (STOPS[i + 1][1][j] - v) * f); });
      return 'rgb(' + c[0] + ',' + c[1] + ',' + c[2] + ')';
    }
  }
  return 'rgb(228,170,145)';
}

/* clip path for panel a — heatmap, hatching AND contours all live inside */
var clipA = draw.rect(A.s, A.s).move(A.x0, A.y0);
var gA = draw.group(); gA.clipWith(clipA);

/* ── Panel a: heatmap ── */
var NG = 36;
for (var i = 0; i < NG; i++) for (var j = 0; j < NG; j++) {
  var p0 = PHI0[0] + (i + 0.5) / NG * 2;
  var p1 = PHI1[0] + (j + 0.5) / NG * 2;
  gA.rect(A.s / NG + 0.6, A.s / NG + 0.6)
