var LAM1 = tr/2 - disc, LAM2 = tr/2 + disc;
var THETA = 0.5 * Math.atan2(2*QC, QA - QB) * 180 / Math.PI;
[0.15, 0.4, 0.9, 1.8, 3.2, 5.5].forEach(function (k) {
  var rx = Math.sqrt(k / LAM1), ry = Math.sqrt(k / LAM2);
  gA.ellipse(2 * rx * A.s / 2, 2 * ry * A.s / 2)
    .center(ax(MIN.p0), ay(MIN.p1))
    .fill('none').stroke({ color: '#bbb', width: 1.1, opacity: 0.45 })
    .transform({ rotate: -THETA, cx: ax(MIN.p0), cy: ay(MIN.p1) });
});

/* panel a frame, ticks, labels */
draw.rect(A.s, A.s).move(A.x0, A.y0).fill('none').stroke({ color: '#222', width: 1.5 });
[[0, '0.0'], [0.5, '0.5'], [1, '1.0'], [1.5, '1.5'], [2, '2.0']].forEach(function (t) {
  draw.line(ax(t[0]), A.y0 + A.s, ax(t[0]), A.y0 + A.s + 5).stroke('#222');
  draw.text(t[1]).center(ax(t[0]), A.y0 + A.s + 16).font({ size: 12, fill: '#333' });
});
[[-1, '-1.0'], [-0.5, '-0.5'], [0, '0.0'], [0.5, '0.5'], [1, '1.0']].forEach(function (t) {
  draw.line(A.x0 - 5, ay(t[0]), A.x0, ay(t[0])).stroke('#222');
  draw.text(t[1]).center(A.x0 - 20, ay(t[0]) + 4).font({ size: 12, fill: '#333' });
});
draw.text('Intercept, φ₀').center(A.x0 + A.s / 2, A.y0 + A.s + 36).font({ size: 15, fill: '#111' });
draw.text('Slope, φ₁').center(A.x0 - 46, A.y0 + A.s / 2).font({ size: 15, fill: '#111' }).rotate(-90, A.x0 - 46, A.y0 + A.s / 2);
draw.text('Loss, L[φ]').center(A.x0 + A.s / 2, A.y0 - 18).font({ size: 17, fill: '#111' });
draw.text('a)').font({ size: 18, fill: '#111' }).move(10, 20);

/* ── Descent trajectory: respread to the source's coordinates so labels 2/3/4 don't collide ── */
