for (var k = 0; k < TRAJ.length - 1; k++) {
  var x1 = ax(TRAJ[k][0]), y1 = ay(TRAJ[k][1]), x2 = ax(TRAJ[k+1][0]), y2 = ay(TRAJ[k+1][1]);
