  gTrail.polygon('0,0 ' + (-asz) + ',' + (-asz/2) + ' ' + (-asz) + ',' + (asz/2))
    .fill('#bbb').center((x1+x2)/2, (y1+y2)/2).transform({ rotate: ang*180/Math.PI, cx: (x1+x2)/2, cy: (y1+y2)/2 });
}
TRAJ.forEach(function (p, k) {
  var c = gTrail.circle(17).center(ax(p[0]), ay(p[1])).fill(TEALS[k]).stroke({ color: '#555', width: 1 });
  c.attr('data-tip', 'Step ' + k + ': φ₀=' + p[0].toFixed(2) + ', φ₁=' + p[1].toFixed(2) + ', L=' + loss(p[0], p[1]).toFixed(2));
